for (number, vertices) in enumerate(polygons)
    twice_area, perimeter = 0, 0.0
    for i in eachindex(vertices)
        x, y = vertices[i]
        next_x, next_y = vertices[mod1(i+1, length(vertices))]
    end
    @printf(
        "polygon %d: area=%.1f perimeter=%.3f\n",
        number,
        abs(twice_area)/2,
        perimeter
    )
